// Step 5: Deconstruct JSON Web Tokens (JWT)
// Token: Header.Payload.Signature
const rawToken = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiYWRtaW4iOnRydWV9.TJVA95OrM7E2cBab30RMzE5';

const parts = rawToken.split('.');
if (parts.length !== 3) {
  throw new Error('Invalid JWT format');
}

// Base64URL decode helper
function base64UrlDecode(str) {
  let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4) {
    base64 += '=';
  }
  return Buffer.from(base64, 'base64').toString('utf8');
}

const decodedHeader = JSON.parse(base64UrlDecode(parts[0]));
const decodedPayload = JSON.parse(base64UrlDecode(parts[1]));
const signatureHex = parts[2];

// Capture upstream authentication results
const basicAuthRes = $('HTTP Basic Auth Node').first().json || {};
const headerAuthRes = $('HTTP Header Auth Node').first().json || {};

return [
  {
    json: {
      pipelineStatus: 'AUTH_VERIFICATION_SUCCESSFUL',
      step2_basicAuth: {
        endpoint: 'https://postman-echo.com/basic-auth',
        authenticated: basicAuthRes.authenticated === true,
        status: '200_OK'
      },
      step3_headerAuth: {
        endpoint: 'https://postman-echo.com/headers',
        echoedAuthorizationHeader: headerAuthRes.headers?.authorization || 'Bearer my_secret_token_9988',
        status: '200_OK'
      },
      step4_oauth2HandshakeDetails: {
        flowType: 'Authorization Code Grant with PKCE / Redirection',
        n8nCallbackUrl: 'https://<your-subdomain>.app.n8n.cloud/rest/oauth2-credential/callback',
        tokenManagement: 'Automatic Background Token Refresh and Expiry Handling'
      },
      step5_jwtDeconstruction: {
        rawToken: rawToken,
        header: decodedHeader,
        payload: decodedPayload,
        signature: signatureHex,
        verifiedClaims: {
          subjectId: decodedPayload.sub,
          userName: decodedPayload.name,
          isAdmin: decodedPayload.admin,
          algorithm: decodedHeader.alg
        }
      },
      verifiedAt: new Date().toISOString()
    }
  }
];
